package pl.zagranietyper.parser;import org.junit.jupiter.api.Test;import pl.zagranietyper.model.*;import static org.junit.jupiter.api.Assertions.*;
class FootballTeamStatisticComparisonSyntaxAdapterTest {private final FootballTeamStatisticComparisonSyntaxAdapter p=new FootballTeamStatisticComparisonSyntaxAdapter();@Test void parsesHomeAwayAndExplicitOpponent(){var h=p.parse("Tottenham wykona więcej rzutów rożnych","Tottenham","Arsenal");assertTrue(h.parsed());assertEquals(FootballFixtureStatisticsSnapshot.TeamSide.HOME,h.condition().selectedSide());var a=p.parse("Arsenal mniej strzałów od Tottenham","Tottenham","Arsenal");assertTrue(a.parsed());assertEquals(FootballTeamStatisticComparisonCondition.Relation.LESS_THAN_OPPONENT,a.condition().relation());}@Test void rejectsUnsafeShapes(){assertFalse(p.parse("Tottenham -1.5 rzutów rożnych","Tottenham","Arsenal").parsed());assertFalse(p.parse("Tottenham więcej rożnych w 1 połowie","Tottenham","Arsenal").parsed());assertFalse(p.parse("Kane więcej strzałów","Tottenham","Arsenal").parsed());assertFalse(p.parse("Tottenham wygra i wykona więcej rożnych","Tottenham","Arsenal").parsed());assertFalse(p.parse("Unknown więcej fauli","Tottenham","Arsenal").parsed());}}
